import{_ as o,o as a,c as t,a2 as d}from"./chunks/framework.YKbyQ3zk.js";const g=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),c={name:"changelog.md"};function s(n,e,r,i,h,l){return a(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to this project are listed here, in the form of <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>. The project follows <a href="https://semver.org" target="_blank" rel="noreferrer">semantic versioning</a> from 0.1.0. Before 1.0.0 a minor version may contain breaking changes, and each one is listed under its version with the steps to upgrade.</p><h2 id="unreleased" tabindex="-1">[Unreleased] <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;[Unreleased]&quot;">​</a></h2><h2 id="011---2026-11-22" tabindex="-1">[0.1.1] - 2026-11-22 <a class="header-anchor" href="#011---2026-11-22" aria-label="Permalink to &quot;[0.1.1] - 2026-11-22&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>A documentation address: each package&#39;s <code>homepage</code> and the links at the end of its README now point to the docs site at <a href="https://weyaisoft.github.io/evo-auth-docs/" target="_blank" rel="noreferrer">https://weyaisoft.github.io/evo-auth-docs/</a>, so the npm pages link the guides and the changelog.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>The README, <code>docs/server.md</code> and the three quickstarts install from the npm registry (<code>@evo-auth/*@0.1.1</code>) and no longer say Evo Auth is not on npm or must be installed from tarballs. <code>evo-auth init</code> already printed the registry install line; <code>--from</code> still prints the tarball form.</li><li>The docs site builds for the path of the documentation address (<code>/evo-auth-docs/</code>), so <code>pnpm --filter site build</code> needs no <code>--base</code> flag.</li></ul><p>No breaking changes.</p><h2 id="010---2026-11-17" tabindex="-1">[0.1.0] - 2026-11-17 <a class="header-anchor" href="#010---2026-11-17" aria-label="Permalink to &quot;[0.1.0] - 2026-11-17&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><p>The first release has six packages, all at 0.1.0 and all under the MIT licence.</p><ul><li><code>@evo-auth/core</code>: the sign-in protocol (GitHub sign-in, sessions with rotating refresh tokens, short-lived signed access tokens), the cryptography, the configuration and its validation, and the <code>evo-auth</code> command line (<code>init</code>, <code>keys generate</code>, <code>keys rotate</code>, <code>keys activate</code>, <code>check</code>). It has no runtime dependency and uses only Web-standard globals.</li><li><code>@evo-auth/convex</code>: a Convex component named <code>evoauth</code> that stores users, accounts, sessions, rate-limit counters and auth events, with <code>registerRoutes</code>, <code>createAuthApi</code>, <code>authConfigProvider</code> and <code>getEvoIdentity</code> for the app that installs it.</li><li><code>@evo-auth/react</code>: <code>AuthProvider</code>, the <code>useAuth</code>, <code>useUser</code> and <code>useSessions</code> hooks, the signed-in and signed-out controls, and the <code>SignIn</code>, <code>UserButton</code> and <code>UserProfile</code> components, with a stylesheet.</li><li><code>@evo-auth/nextjs</code>: the Next.js App Router integration for <code>@evo-auth/core</code> and <code>@evo-auth/react</code>: <code>createEvoAuth</code> with its server, <code>./client</code> and <code>./admin</code> entry points.</li><li><code>@evo-auth/react-router</code>: the React Router framework-mode integration for <code>@evo-auth/core</code> and <code>@evo-auth/react</code>, with its <code>./client</code> entry point.</li><li><code>@evo-auth/server</code>: Evo Auth without Convex, on one Node process (<code>&gt;=26.3 &lt;27</code>) and one SQLite file. It is a storage adapter that passes core&#39;s contract suite, schema versions with <code>migrate</code> and a copy beside the file before a migration, stored jobs with a lease so that one server runs per file, <code>createServer</code> (its <code>handler</code>, <code>start()</code>, <code>listen()</code> and <code>close()</code>), and the <code>evo-auth-server</code> command (<code>start</code>, <code>migrate</code>, <code>backup</code>, <code>check</code>, <code>users ban|unban|delete</code>, <code>webhooks failed|redeliver</code>). <code>evo-auth init --server</code> writes its options file. The guide is <a href="./server.html">docs/server.md</a>.</li><li>Signed webhooks for an app whose database is elsewhere: <code>user.created</code>, <code>user.updated</code> and <code>user.deleted</code> in the Standard Webhooks format, delivered at least once with retries and written in the same transaction as the change. <code>verifyWebhook</code> and <code>WebhookError</code> in <code>@evo-auth/core</code> check a delivery in any backend.</li><li>A second example app, <code>examples/tanstack-server</code>: TanStack Start on the server, with its own users table fed by webhooks.</li><li>Replacing <code>EVO_AUTH_SECOND_FACTOR_KEY</code> without anyone setting two-step sign-in up again: <code>EVO_AUTH_SECOND_FACTOR_KEY_PREVIOUS</code> holds the old key while authenticator and backup codes open under either key, each step a person passes moves them to the new key, and a reseal moves everyone else: <code>evo-auth-server second-factor reseal</code> on the standalone server, and the app&#39;s own action from <code>createSecondFactorReseal</code> on Convex (<code>resealSecondFactors</code> in core). <code>evo-auth check</code> and <code>evo-auth-server check</code> warn while the previous key is set. Backup codes are stored as seals of each code&#39;s SHA-256 under the second-factor key, so they move with it. See <a href="./rotating-secrets.html#replacing-evo_auth_second_factor_key">Rotating secrets</a>.</li><li><code>devConsoleSender()</code> in <code>@evo-auth/core</code>, the development sender <code>evo-auth init --stack</code> sets: it prints each message&#39;s code and link in the auth side&#39;s terminal instead of sending it. <code>validateConfig</code> refuses it without <code>cookies.devMode</code>, and each send is refused, logged as <code>email.send_failed</code>, unless the host says the auth side is local: <code>evo-auth-server</code> once <code>listen()</code> has bound a loopback address, and the Convex adapter when the deployment&#39;s <code>CONVEX_CLOUD_URL</code> is on a loopback host. A host says so through the optional <code>localAuthSide</code> member of <code>auth.handler</code>&#39;s and <code>auth.sendEmailChallenge</code>&#39;s context, and a sender reads it from its second argument.</li></ul>',13)])])}const p=o(c,[["render",s]]);export{g as __pageData,p as default};
